param([Parameter(Mandatory=$true)][string]$Executable,[Parameter(Mandatory=$true)][string]$Runtime,[Parameter(Mandatory=$true)][string]$OutputDirectory)
$ErrorActionPreference='Stop';if(Test-Path $OutputDirectory){throw 'Fresh validation directory required'};$root=(New-Item -ItemType Directory $OutputDirectory).FullName;$exe=(Resolve-Path $Executable).Path;$runtimePath=(Resolve-Path $Runtime).Path;New-Item -ItemType Directory "$root/inputs"|Out-Null
function FloatBytes([string]$Path){$tokens=(Get-Content -LiteralPath $Path -Raw) -split '\s+'|Where-Object{$_ -ne ''};$n=[int]$tokens[0]*[int]$tokens[1];if($tokens.Count -ne $n+2){throw 'Invalid fixture count'};$s=New-Object IO.MemoryStream;$b=New-Object IO.BinaryWriter($s);for($i=0;$i -lt $n;$i++){$b.Write([single]::Parse($tokens[$i+2],[Globalization.CultureInfo]::InvariantCulture))};$b.Flush();$data=$s.ToArray();$b.Dispose();return ,$data}
function WritePFM([string]$Path,[byte[]]$Data,[int]$W,[int]$H){$s=[IO.File]::Open($Path,[IO.FileMode]::CreateNew);$b=New-Object IO.BinaryWriter($s);$b.Write([Text.Encoding]::ASCII.GetBytes("Pf`n$W $H`n-1.0`n"));for($y=$H-1;$y -ge 0;$y--){for($x=0;$x -lt $W;$x++){$b.Write([BitConverter]::ToSingle($Data,4*($y*$W+$x)))}};$b.Dispose()}
function EqualBytes([string]$Actual,[byte[]]$Expected){$sha=[Security.Cryptography.SHA256]::Create();$digest=([BitConverter]::ToString($sha.ComputeHash($Expected))).Replace('-','');if((Get-FileHash -LiteralPath $Actual).Hash -ne $digest){throw "Changed bytes:$Actual"}}
$records=@();$firstInput=$null
foreach($pattern in @('asymmetric','impulse','hdr_ramp')){$a=Get-Content "validation/actual_content_stress_639284716222632999/$pattern/assets_cpu_filters.json" -Raw|ConvertFrom-Json
 foreach($shape in @(@(80,96),@(96,80))){$h=$shape[0];$w=$shape[1];$tag="${pattern}_h${h}_w${w}";$orientation="h${h}_w${w}";$ref=FloatBytes "$($a.nativeFilters)/$orientation/ref_luminance.txt";$test=FloatBytes "$($a.nativeFilters)/$orientation/test_luminance.txt";$refFile="$root/inputs/${tag}_ref.pfm";$testFile="$root/inputs/${tag}_test.pfm";WritePFM $refFile $ref $w $h;WritePFM $testFile $test $w $h;if(!$firstInput){$firstInput=@($refFile,$testFile)}
 $output="$root/$tag";$ErrorActionPreference='Continue';& $exe --method HDRVDP3 --enable-validation --input $testFile --ref $refFile --hdrvdp3-runtime $runtimePath --hdrvdp3-export $output *> "$root/$tag.log";$code=$LASTEXITCODE;$ErrorActionPreference='Stop';$log=Get-Content "$root/$tag.log" -Raw;if($code -ne 0 -or $log -match 'VUID-|Validation Error|\[ERROR\]'){throw "CLI failure:$tag"}
 EqualBytes "$output/input_reference.f32" $ref;EqualBytes "$output/input_test.f32" $test;EqualBytes "$output/scores.f32" (FloatBytes "$($a.nativeMasking)/$orientation/scores.txt")
 EqualBytes "$output/reference_P.f32" (FloatBytes "$($a.visual)/stages/$orientation/reference_P.txt");EqualBytes "$output/test_P.f32" (FloatBytes "$($a.visual)/stages/$orientation/test_P.txt");EqualBytes "$output/log_adaptation.f32" (FloatBytes "$($a.visual)/$orientation/log_La.txt")
 $score=[IO.File]::ReadAllBytes("$output/scores.f32");$records+=[pscustomobject]@{case=$tag;Q=[BitConverter]::ToSingle($score,0);Q_JOD=[BitConverter]::ToSingle($score,4);native_score_bits=$true;input_P_log_bits=$true};$records|ConvertTo-Json|Set-Content "$root/results.json";Write-Output "$tag CLI native bits PASS"
 }}
$spectral='validation/asset_generation_639281159480285385/assets_verified/spectral'
$negatives=@(@{name='ppd60';args=@('--hdrvdp3-ppd','60')},@{name='age60';args=@('--hdrvdp3-age','60','--hdrvdp3-spectral-data',$spectral)},@{name='spectral_override';args=@('--hdrvdp3-spectral-data',$spectral)})
foreach($case in $negatives){$output="$root/reject_$($case.name)";$extra=$case.args;$ErrorActionPreference='Continue';& $exe --method HDRVDP3 --input $firstInput[1] --ref $firstInput[0] --hdrvdp3-runtime $runtimePath --hdrvdp3-export $output @extra *> "$root/reject_$($case.name).log";$code=$LASTEXITCODE;$ErrorActionPreference='Stop';if($code -eq 0 -or (Test-Path $output)){throw 'Unsupported view accepted'};$log=Get-Content "$root/reject_$($case.name).log" -Raw;if($log -notmatch 'requires30ppd/age24'){throw 'Unexpected negative failure'}}
Get-FileHash -LiteralPath $exe,$PSCommandPath,"$runtimePath/pathway.runtime"|Select-Object Path,Hash|ConvertTo-Json|Set-Content "$root/hashes.json"
Set-Content "$root/PASS.txt" 'Six original PFM CLI pairs:native Q/Q_JOD bits and original input/P/log buffers identical;three unsupported viewing/spectral settings rejected without export;no Vulkan errors.'
